		"hapi.fhir.mdm_enabled=true"
})
class MdmTest {
	@Autowired
	INicknameSvc nicknameService;

	@Autowired
	SubscriptionSettings subscriptionSettings;

	@Test
	void testApplicationStartedSuccessfully() {
